pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 ether);
        vm.prank(user);
        (bool ok,) = address(c).call{value: 1 ether}("");
        require(ok, "deposit failed");

        // Make user's fallback revert
        vm.prank(user);
        vm.etch(user, hex"fe");  // just REVERT opcode

        bool withdrawSucceeded;
        try c.withdraw() {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // The correct contract reverts due to require, so withdrawSucceeded should be false.
        // The buggy contract does not revert, so withdrawSucceeded would be true.
        // We assert that the transfer did NOT happen: balances[user] should still be 1 ether if revert occurred.
        assertTrue(!withdrawSucceeded);
    }
}

