pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy a receiver that rejects ether
        address receiver = address(new RejectEther());

        // fund the receiver
        vm.deal(receiver, 1 ether);

        // receiver deposits into C
        vm.prank(receiver);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "deposit failed");

        // now receiver tries to withdraw - the external call to receiver will fail
        vm.prank(receiver);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // In reference contract, the require on send result reverts the whole tx
        // so the withdraw call should revert (ok == false)
        // In buggy contract, the require is removed, so the call succeeds and balance becomes 0
        // We assert that the call reverted (reference behavior)
        assertTrue(!ok);
    }
}

contract RejectEther {
    receive() external payable {
        revert("I reject ether");
    }
}

