pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Rejector {
    receive() external payable { revert("reject"); }
}

contract InvMutTest is Test {
    C c;
    Rejector rejector;
    function setUp() public { 
        c = new C(); 
        rejector = new Rejector();
    }
    function testRegression_property() public {
        // Alice (the test contract) sends 1 ether to the Rejector contract
        vm.deal(address(this), 10 ether);
        (bool sent, ) = address(rejector).call{value: 1 ether}("");
        require(sent, "initial send failed");
        // Rejector deposits through fallback
        vm.prank(address(rejector));
        (bool okDeposit, ) = address(c).call{value: 1 ether}("");
        require(okDeposit, "deposit failed");
        // Rejector calls withdraw; on reference it reverts, on buggy it passes and sets balance to 0
        bool withdrawReverted;
        vm.prank(address(rejector));
        try c.withdraw() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        // On reference, withdraw should revert (because call to Rejector reverts), so withdrawReverted == true
        // On buggy, withdraw passes and resets balance, then Rejector can withdraw again
        assertTrue(withdrawReverted);
    }
}

