pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);

        // Alice deposits 1 ether via contract that rejects direct ether
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        assertTrue(sent, "initial deposit failed");

        // Bob deposits 2 ether (normal address)
        vm.deal(bob, 2 ether);
        vm.prank(bob);
        (sent, ) = address(c).call{value: 2 ether}("");
        assertTrue(sent, "bob deposit failed");

        // Bob withdraws successfully first
        vm.prank(bob);
        c.withdraw();
        assertEq(c.balances(bob), 0, "bob balance should be 0 after withdraw");

        // Alice withdraws — Alice address has no receive, so send will fail
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(!ok, "withdraw should revert for Alice");
        // After the failed withdraw, reference keeps balance 1 ether, buggy sets to 0
        assertTrue(c.balances(alice) == 1 ether, "Alice balance should remain 1 ether");
    }
}

