pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        (bool okDeposit, ) = address(c).call{value: 1 ether}("");
        require(okDeposit, "deposit failed");

        // Alice calls withdraw
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // On the reference, the withdraw succeeds (ok == true). On the bug, it also succeeds?
        // But we need a different divergence: Let's make it so that the reference reverts
        // and the bug does not. Use send that fails: alice as a contract that rejects ether.
        // To keep it simple: deploy a contract that always reverts on receive.
        // However that requires a contract. Simpler: Use selfdestruct to force balance change.
        // Actually, we can use the fact that after withdraw in bug, balances[alice] still 1 ether.
        // So alice withdraws again, reference reverts (balance=0), bug succeeds again.
        // We'll test the second withdraw: reference reverts, bug succeeds.
        vm.prank(alice);
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        assertTrue(ok2 == false, "Expected revert on second withdraw for reference");
    }
}

