import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);

        vm.prank(alice);
        c.fallback{value: 1 ether}();

        vm.prank(bob);
        c.fallback{value: 1 ether}();

        // Alice withdraws first - this succeeds
        vm.prank(alice);
        c.withdraw();

        // Bob withdraws - in reference, reentrancy lock causes revert because
        // Bob's balance is still 1 ether after sending (lock prevents reset before send),
        // but function re-enters? Actually: lock is applied, send succeeds, then reset fails.
        // Wait: need to re-analyze. Let's use a different approach:
        // Alice withdraws, then Bob tries to withdraw - in reference, after Alice's withdraw
        // balances[Bob] remains 1 ether. Bob's withdraw sends him 1 ether and resets to 0.
        // In buggy, sends 1 ether but doesn't reset. Difference: after Bob's withdraw,
        // c.balances(bob) is 0 in reference, 1 ether in buggy.
        vm.prank(bob);
        c.withdraw();

        uint256 bobBalRef = c.balances(bob);
        assertTrue(bobBalRef == 0, "Bug: Bob's balance not reset to 0");
    }
}

